insert into public.pages (slug,title,legend,sections,published,is_template) values ('ole','Mailform Ole','Skriv til Ole','[{"id":"s1","kind":"html","html":"<div class=\"widget widget--zone-widget\" data-name=\"content\">\n  <div class=\"bk-content-text content widget__content\">\n    <span class=\"js-text-content content-block\">\n      <a href=\"http://mailform.dk/gratis\" target=\"_self\"><img alt=\"droosjpg\" src=\"https://files.builder.nu/73/20/73208252-87a4-431d-b30d-994f8dfc3533.jpg\"></a><br>\n    </span>\n  </div>\n</div>"},{"id":"s2","kind":"html","html":"<div class=\"widget widget--zone-widget\" data-name=\"responsivecolumns\">\n  <div class=\"bk-responsivecolumns responsivecolumns widget__responsivecolumns\">\n    <section class=\"bk-zone column columns-two-left\"></section>\n    <section class=\"bk-zone column columns-two-right\">\n      <div class=\"widget widget--zone-widget\" data-name=\"contactform\">\n        <div data-mf-form=\"\"></div>\n      </div>\n    </section>\n  </div>\n</div>"},{"id":"s3","kind":"html","html":"<div class=\"widget widget--zone-widget\" data-name=\"content\">\n  <div class=\"bk-content-text content widget__content\">\n    <span class=\"js-text-content content-block\">\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"https://mailform.dk/chosen\" target=\"_blank\"><b><span class=\"wysiwyg-font-size-12\">The Chosen'' er et crowd-finansieret filmprojekt  baseret på livet med Jesus fra Nazareth  &gt;&gt;&gt;</span></b></a></span></b></div>\n<div style=\"text-align: center;\"><b><a href=\"https://mailform.dk/chosen\" target=\"_blank\"><img alt=\"chosentvjpg\" src=\"https://files.builder.nu/da/9e/da9e2e34-fbf3-4268-83b2-f963ec6d1122.jpg\" width=\"987\" height=\"83\"></a></b></div>\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"http://mailform.dk/jews\" target=\"_blank\"><b>Why jews don’t believe in Jesus &gt;&gt;&gt; Hvorfor jøder ikke tror på Jesus  &gt;&gt;&gt;</b></a>&nbsp; <a href=\"https://ifoundshalom.com/\" target=\"_blank\">&gt;&gt;&gt;</a></span></b></div>\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"https://mailform.dk/quran\" target=\"_self\"><b>Who is Jesus/Isa from the Quran &gt;&gt;&gt;</b></a>&nbsp;&nbsp; <a href=\"https://mailform.dk/koranen\" target=\"_blank\"><b>Hvem er Jesus/Isa i koranen &gt;&gt;&gt;</b></a></span></b></div>\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"https://debat.verdensbilledet.dk/imam.mp4\" target=\"_blank\"><b>Imam about Jesus in the Quran &gt;&gt;&gt; Imam om Jesus i Koranen &gt;&gt;&gt;</b></a></span></b></div>\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"http://archive.mailform.dk/ravi-abraham.mp3\" target=\"_blank\"><b>Abraham about Jesus &gt;&gt;&gt;</b></a> &nbsp; <a href=\"http://archive.mailform.dk/ravi-only.mp3\" target=\"_blank\"><b>Did Jesus die on the cross &gt;&gt;&gt;</b></a></span></b></div>\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"https://mailform.dk/nabeel\" target=\"_blank\"><b>Testimony of Nabeel Qureshi &gt;&gt;&gt;</b></a> &nbsp; <a href=\"http://archive.mailform.dk/isa.mp4\" target=\"_blank\"><b>Isa in the quran &gt;&gt;&gt;</b></a></span></b></div>\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"http://teamjesus.dk/raviz.mp4\" target=\"_blank\"><b>Where we went wrong with Ravi Zacharias &gt;&gt;&gt;</b></a></span></b></div>\n<div style=\"text-align: center;\"><b><a href=\"https://www.hvemerjesus.dk\" target=\"_blank\"><i><span class=\"wysiwyg-font-size-12\">Hvem er Jesus</span></i><span class=\"wysiwyg-font-size-12\">&nbsp; forklaret på tegnefilm &gt;&gt;&gt;</span></a></b></div>\n<div style=\"text-align: center;\"><b><a href=\"http://debat.verdensbilledet.dk/sodogom.mp4\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\"><b>Sodoma og Gomorra virkelig &gt;&gt;&gt;</b></span></a> <a href=\"http://debat.verdensbilledet.dk/sodomgm.mp4\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\">&gt;&gt;&gt;</span></a></b></div>\n<div style=\"text-align: center;\"><b><a href=\"https://mailform.dk/chn001\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\"><b>Chinas first religion &gt;&gt;&gt;</b></span></a>&nbsp; <a href=\"https://mailform.dk/chn002\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\"><b>&gt;&gt;&gt;</b></span></a></b></div>\n<div style=\"text-align: center;\"><b><a href=\"https://mailform.dk/kenthv\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\"><b>Bibelen vs videnskab &gt;&gt;&gt;</b></span></a></b></div>\n<div style=\"text-align: center;\"><b><a href=\"http://debat.verdensbilledet.dk/thebible.mp4\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\"><b>The Bible histore &gt;&gt;&gt;</b></span></a></b></div>\n<div style=\"text-align: center;\"><b><a href=\"http://mailform.dk/dnt\" target=\"_self\"><b><span class=\"wysiwyg-font-size-12\">Læs i Bibelen  &gt;&gt;&gt;</span></b></a></b></div>\n<div style=\"text-align: center;\"><b><a href=\"http://debat.verdensbilledet.dk/onemore.mp4\" target=\"_blank\"><b><span class=\"wysiwyg-font-size-12\">One more &gt;&gt;&gt;</span></b></a></b></div>\n    </span>\n  </div>\n</div>"},{"id":"s4","kind":"html","html":"<div class=\"widget widget--zone-widget\" data-name=\"content\">\n  <div class=\"bk-content-text content widget__content\">\n    <span class=\"js-text-content content-block\">\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"http://teamjesus.dk/elias72.mp3\" target=\"_blank\">Et interview fra hjertet &gt;&gt;&gt;</a> <a href=\"http://teamjesus.dk/free001.mp4\" target=\"_blank\">&gt;&gt;&gt;</a></span></b></div>\n<div style=\"text-align: center;\"><a href=\"http://teamjesus.dk/elias72.mp3\" target=\"_blank\"><img alt=\"testimonyjpg\" src=\"https://files.builder.nu/9a/f8/9af890cb-55a3-4296-b80a-6d969c8b1e0d.jpg\"></a></div>\n    </span>\n  </div>\n</div>"},{"id":"s5","kind":"html","html":"<div class=\"widget widget--zone-widget\" data-name=\"content\">\n  <div class=\"bk-content-text content widget__content\">\n    <span class=\"js-text-content content-block\">\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"http://teamjesus.dk/elias72.mp3\" target=\"_blank\"><img alt=\"gudstestamentejpg\" src=\"https://files.builder.nu/44/53/4453c7a9-43dd-4327-bc70-65489ea29e05.jpg\" width=\"995\" height=\"62\"><br>Det Nye Testamente, Hebræerbrevet, Kapitel 9<br></a></span></b></div>\n<div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><a href=\"http://teamjesus.dk/elias72.mp3\" target=\"_blank\">\"Derfor er Kristus formidler af en ny pagt, for at de kaldede kan få den evige arv, der er lovet, ved at han er død til forløsning fra overtrædelserne under den første pagt. For hvor der er et testamente, er det nødvendigt, at testators død godtgøres; et testamente får jo først betydning ved dødsfald, da det ikke har nogen som helst virkning, så længe han, som oprettede det, lever.\" </a></span></b></div>\n    </span>\n  </div>\n</div>"},{"id":"s6","kind":"html","html":"<div class=\"widget widget--zone-widget\" data-name=\"content\">\n  <div class=\"bk-content-text content widget__content\">\n    <span class=\"js-text-content content-block\">\n<div style=\"text-align: center;\"><b><a href=\"https://mailform.dk/mlink\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\">The Missing Link &gt;&gt;&gt;</span></a></b><br><a href=\"https://verdensbilledet.dk/universet#evangeliet\" target=\"_blank\"><img alt=\"missinglinkjpeg\" src=\"https://files.builder.nu/34/41/3441970c-7bc3-4e0e-b40c-e122971fd0c0.jpeg\" width=\"1018\" height=\"123\"></a></div>\n<div style=\"text-align: center;\"><a href=\"https://mailform.dk/missinglink\"><span class=\"wysiwyg-font-size-12\"><i><b>...the missing links &gt;&gt;&gt;</b></i><img alt=\"missingjpg\" src=\"https://files.builder.nu/13/1c/131c3aa1-ed00-43d6-b5c6-8d1a0d13a4f6.jpg\" width=\"996\" height=\"184\"></span></a></div>\n    </span>\n  </div>\n</div>"},{"id":"s7","kind":"html","html":"<div class=\"widget widget--zone-widget\" data-name=\"content\">\n  <div class=\"bk-content-text content widget__content\">\n    <span class=\"js-text-content content-block\">\n<div style=\"text-align: center;\"><a href=\"http://teamjesus.dk/emilsv.mp3\" target=\"_blank\"><img alt=\"emilsvjpg\" src=\"https://files.builder.nu/6f/64/6f6479f8-fae3-4340-8f7a-f79a4fc5cf33.jpg\" width=\"977\" height=\"18\"></a></div>\n<div style=\"text-align: center;\"><a href=\"http://teamjesus.dk/juliesv.mp3\" target=\"_blank\"><img alt=\"juliesvjpg\" src=\"https://files.builder.nu/00/20/0020def8-1811-41a6-bec8-f2c156a9ccca.jpg\" width=\"977\" height=\"18\"></a></div>\n    </span>\n  </div>\n</div>"},{"id":"s8","kind":"html","html":"<div class=\"widget widget--zone-widget\" data-name=\"content\">\n  <div class=\"bk-content-text content widget__content\">\n    <span class=\"js-text-content content-block\">\n<div style=\"text-align: center;\"><b><a href=\"http://debat.verdensbilledet.dk/rep.mp4\" target=\"_blank\"><img alt=\"repjpg\" src=\"https://files.builder.nu/40/5f/405fea4c-f8d1-48f6-b696-2f9fac5f72ba.jpg\" width=\"977\" height=\"37\"></a></b></div>\n<div style=\"text-align: center;\"><b><a href=\"http://teamjesus.dk/rosti.mp3\" target=\"_blank\"><img alt=\"linerjpeg\" src=\"https://files.builder.nu/09/21/09213997-ac86-41b8-9922-58f1c3bcafed.jpeg\" width=\"977\" height=\"18\"></a></b></div>\n    </span>\n  </div>\n</div>"},{"id":"s9","kind":"placeholder","html":""},{"id":"s10","kind":"placeholder","html":""},{"id":"s11","kind":"html","html":"<div class=\"widget widget--zone-widget\" data-name=\"content\">\n  <div class=\"bk-content-text content widget__content\">\n    <span class=\"js-text-content content-block\">\n<div style=\"text-align: center;\"><a href=\"https://mailform.dk/freee\"